const listIntegrations = `-- name: ListIntegrations :many
SELECT
  i.id, i.user_id, i.name, i.description, i.callback_base_url, i.daily_limit, i.max_file_size_bytes, i.rate_limit_per_minute, i.max_concurrent_downloads, i.allowed_ips, i.active, i.created_by, i.created_at, i.updated_at, i.deleted_at,
  u.email AS service_email,
  COUNT(d.id) FILTER (WHERE d.deleted_at IS NULL)::bigint AS downloads_total,
  COUNT(d.id) FILTER (
    WHERE d.deleted_at IS NULL
      AND d.created_at >= TIMEZONE('UTC', TIMEZONE('America/Sao_Paulo', CURRENT_DATE))
      AND d.created_at <  TIMEZONE('UTC', TIMEZONE('America/Sao_Paulo', CURRENT_DATE + INTERVAL '1 day'))
  )::bigint AS downloads_today,
  COUNT(d.id) FILTER (
    WHERE d.deleted_at IS NULL AND d.status IN ('PENDING', 'PROCESSING', 'RETRYING')
  )::bigint AS downloads_active,
  COALESCE(SUM(d.file_size_bytes) FILTER (
    WHERE d.deleted_at IS NULL AND d.status = 'COMPLETED'
  ), 0)::bigint AS storage_bytes,
  (
    SELECT COUNT(*) FROM integration_api_keys k
    WHERE k.integration_id = i.id AND k.revoked_at IS NULL
  )::bigint AS active_keys,
  -- O cast explícito é necessário: sem ele o sqlc não consegue inferir o tipo
  -- da subconsulta e gera interface{}, que a camada de cima não sabe formatar.
  (
    SELECT MAX(k.last_used_at) FROM integration_api_keys k
    WHERE k.integration_id = i.id
  )::timestamptz AS last_used_at
FROM integrations i
JOIN users u ON u.id = i.user_id
LEFT JOIN downloads d ON d.user_id = i.user_id
WHERE i.deleted_at IS NULL
  AND (
    $3::text IS NULL
    OR lower(i.name) LIKE '%' || lower($3::text) || '%'
    OR lower(COALESCE(i.description, '')) LIKE '%' || lower($3::text) || '%'
  )
  AND ($4::boolean IS NULL OR i.active = $4::boolean)
GROUP BY i.id, u.email
ORDER BY i.created_at DESC
LIMIT $1 OFFSET $2
`

type ListIntegrationsParams struct {
	Limit  int32       `json:"limit"`
	Offset int32       `json:"offset"`
	Search pgtype.Text `json:"search"`
	Active pgtype.Bool `json:"active"`
}

type ListIntegrationsRow struct {
	ID                     uuid.UUID          `json:"id"`
	UserID                 uuid.UUID          `json:"user_id"`
	Name                   string             `json:"name"`
	Description            pgtype.Text        `json:"description"`
	CallbackBaseUrl        pgtype.Text        `json:"callback_base_url"`
	DailyLimit             int32              `json:"daily_limit"`
	MaxFileSizeBytes       int64              `json:"max_file_size_bytes"`
	RateLimitPerMinute     int32              `json:"rate_limit_per_minute"`
	MaxConcurrentDownloads int32              `json:"max_concurrent_downloads"`
	AllowedIps             []string           `json:"allowed_ips"`
	Active                 bool               `json:"active"`
	CreatedBy              pgtype.UUID        `json:"created_by"`
	CreatedAt              *time.Time         `json:"created_at"`
	UpdatedAt              *time.Time         `json:"updated_at"`
	DeletedAt              pgtype.Timestamptz `json:"deleted_at"`
	ServiceEmail           string             `json:"service_email"`
	DownloadsTotal         int64              `json:"downloads_total"`
	DownloadsToday         int64              `json:"downloads_today"`
	DownloadsActive        int64              `json:"downloads_active"`
	StorageBytes           int64              `json:"storage_bytes"`
	ActiveKeys             int64              `json:"active_keys"`
	LastUsedAt             *time.Time         `json:"last_used_at"`
}

// Listagem do painel. Os números vêm na mesma consulta porque a tela mostra
// todos eles juntos, e uma chamada por integração transformaria a abertura da
// página em N+1 idas ao banco.
//
// `downloads_today` usa o MESMO corte de dia do contador do usuário comum
// (meia-noite em São Paulo, convertida para UTC). Um corte em UTC faria a cota
// virar às 21h e o painel discordaria da API.
func (q *Queries) ListIntegrations(ctx context.Context, arg ListIntegrationsParams) ([]ListIntegrationsRow, error) {
	rows, err := q.db.Query(ctx, listIntegrations,
		arg.Limit,
		arg.Offset,
		arg.Search,
		arg.Active,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListIntegrationsRow{}
	for rows.Next() {
		var i ListIntegrationsRow
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Name,
			&i.Description,
			&i.CallbackBaseUrl,
			&i.DailyLimit,
			&i.MaxFileSizeBytes,
			&i.RateLimitPerMinute,
			&i.MaxConcurrentDownloads,
			&i.AllowedIps,
			&i.Active,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.DeletedAt,
			&i.ServiceEmail,
			&i.DownloadsTotal,
			&i.DownloadsToday,
			&i.DownloadsActive,
			&i.StorageBytes,
			&i.ActiveKeys,
			&i.LastUsedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

