const markWebhookFailed = `-- name: MarkWebhookFailed :one
UPDATE integration_webhooks
SET last_delivery_at = now(),
    last_status_code = $2,
    last_error = $3,
    consecutive_failures = consecutive_failures + 1,
    updated_at = now()
WHERE id = $1
RETURNING id, integration_id, url, secret, events, include_progress, active, last_delivery_at, last_status_code, last_error, consecutive_failures, disabled_reason, created_at, updated_at, deleted_at
`

type MarkWebhookFailedParams struct {
	ID         uuid.UUID   `json:"id"`
	StatusCode pgtype.Int4 `json:"status_code"`
	Error      pgtype.Text `json:"error"`
}

// O contador de falhas consecutivas é o que permite desligar sozinho um
// endpoint que morreu: sem ele, um destino que responde 500 para sempre
// receberia reentrega eternamente.
func (q *Queries) MarkWebhookFailed(ctx context.Context, arg MarkWebhookFailedParams) (IntegrationWebhook, error) {
	row := q.db.QueryRow(ctx, markWebhookFailed, arg.ID, arg.StatusCode, arg.Error)
	var i IntegrationWebhook
	err := row.Scan(
		&i.ID,
		&i.IntegrationID,
		&i.Url,
		&i.Secret,
		&i.Events,
		&i.IncludeProgress,
		&i.Active,
		&i.LastDeliveryAt,
		&i.LastStatusCode,
		&i.LastError,
		&i.ConsecutiveFailures,
		&i.DisabledReason,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}

const pruneIntegrationRequests = `-- name: PruneIntegrationRequests :execrows

DELETE FROM integration_requests
WHERE created_at < now() - ($1::int * INTERVAL '1 day')
`

// ---------------------------------------------------------------------------
// Retenção
// ---------------------------------------------------------------------------
// As duas tabelas de auditoria crescem a cada chamada e a cada notificação.
// Sem poda, a de requisições passa o histórico de downloads em volume e o
// painel fica lento por dado que ninguém mais vai olhar.
func (q *Queries) PruneIntegrationRequests(ctx context.Context, keepDays int32) (int64, error) {
	result, err := q.db.Exec(ctx, pruneIntegrationRequests, keepDays)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const pruneWebhookDeliveries = `-- name: PruneWebhookDeliveries :execrows
DELETE FROM integration_webhook_deliveries
WHERE (status = 'DELIVERED' AND created_at < now() - ($1::int * INTERVAL '1 day'))
   OR (status <> 'DELIVERED' AND created_at < now() - ($1::int * 3 * INTERVAL '1 day'))
`

// Entregas concluídas são podadas; as que falharam sobrevivem mais tempo,
// porque é justamente nelas que alguém vai procurar o motivo.
func (q *Queries) PruneWebhookDeliveries(ctx context.Context, keepDays int32) (int64, error) {
	result, err := q.db.Exec(ctx, pruneWebhookDeliveries, keepDays)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const revokeIntegrationAPIKey = `-- name: RevokeIntegrationAPIKey :one
UPDATE integration_api_keys
SET revoked_at = COALESCE(revoked_at, now()),
    revoked_reason = COALESCE(revoked_reason, $2)
WHERE id = $1
RETURNING id, integration_id, label, key_prefix, key_hash, last_four, revoked_at, revoked_reason, expires_at, last_used_at, last_used_ip, created_by, created_at
`

type RevokeIntegrationAPIKeyParams struct {
	ID     uuid.UUID   `json:"id"`
	Reason pgtype.Text `json:"reason"`
}

// Revogar é idempotente e preserva o carimbo original: uma segunda revogação
// não deve reescrever a data em que a chave de fato saiu do ar.
func (q *Queries) RevokeIntegrationAPIKey(ctx context.Context, arg RevokeIntegrationAPIKeyParams) (IntegrationApiKey, error) {
	row := q.db.QueryRow(ctx, revokeIntegrationAPIKey, arg.ID, arg.Reason)
	var i IntegrationApiKey
	err := row.Scan(
		&i.ID,
		&i.IntegrationID,
		&i.Label,
		&i.KeyPrefix,
		&i.KeyHash,
		&i.LastFour,
		&i.RevokedAt,
		&i.RevokedReason,
		&i.ExpiresAt,
		&i.LastUsedAt,
		&i.LastUsedIp,
		&i.CreatedBy,
		&i.CreatedAt,
	)
	return i, err
}

const revokeOtherIntegrationAPIKeys = `-- name: RevokeOtherIntegrationAPIKeys :exec
UPDATE integration_api_keys
SET revoked_at = now(),
    revoked_reason = COALESCE(revoked_reason, $2)
WHERE integration_id = $1
  AND id <> $3
  AND revoked_at IS NULL
`

