const updateIntegration = `-- name: UpdateIntegration :one
UPDATE integrations
SET
  name = COALESCE($2, name),
  description = COALESCE($3, description),
  callback_base_url = COALESCE($4, callback_base_url),
  daily_limit = COALESCE($5, daily_limit),
  max_file_size_bytes = COALESCE($6, max_file_size_bytes),
  rate_limit_per_minute = COALESCE($7, rate_limit_per_minute),
  max_concurrent_downloads = COALESCE($8, max_concurrent_downloads),
  -- O array não usa COALESCE com o próprio valor: uma lista VAZIA é uma
  -- escolha legítima ("aceitar qualquer IP"), e COALESCE não sabe distinguir
  -- "não mandei" de "mandei vazio". O sentinela é o NULL do narg.
  allowed_ips = CASE
      WHEN $9::text[] IS NULL THEN allowed_ips
      ELSE $9::text[]
    END,
  active = COALESCE($10, active),
  updated_at = now()
WHERE id = $1
  AND deleted_at IS NULL
RETURNING id, user_id, name, description, callback_base_url, daily_limit, max_file_size_bytes, rate_limit_per_minute, max_concurrent_downloads, allowed_ips, active, created_by, created_at, updated_at, deleted_at
`

type UpdateIntegrationParams struct {
	ID                     uuid.UUID   `json:"id"`
	Name                   pgtype.Text `json:"name"`
	Description            pgtype.Text `json:"description"`
	CallbackBaseUrl        pgtype.Text `json:"callback_base_url"`
	DailyLimit             pgtype.Int4 `json:"daily_limit"`
	MaxFileSizeBytes       pgtype.Int8 `json:"max_file_size_bytes"`
	RateLimitPerMinute     pgtype.Int4 `json:"rate_limit_per_minute"`
	MaxConcurrentDownloads pgtype.Int4 `json:"max_concurrent_downloads"`
	AllowedIps             []string    `json:"allowed_ips"`
	Active                 pgtype.Bool `json:"active"`
}

func (q *Queries) UpdateIntegration(ctx context.Context, arg UpdateIntegrationParams) (Integration, error) {
	row := q.db.QueryRow(ctx, updateIntegration,
		arg.ID,
		arg.Name,
		arg.Description,
		arg.CallbackBaseUrl,
		arg.DailyLimit,
		arg.MaxFileSizeBytes,
		arg.RateLimitPerMinute,
		arg.MaxConcurrentDownloads,
		arg.AllowedIps,
		arg.Active,
	)
	var i Integration
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Name,
		&i.Description,
		&i.CallbackBaseUrl,
		&i.DailyLimit,
		&i.MaxFileSizeBytes,
		&i.RateLimitPerMinute,
		&i.MaxConcurrentDownloads,
		&i.AllowedIps,
		&i.Active,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}

const updateIntegrationWebhook = `-- name: UpdateIntegrationWebhook :one
UPDATE integration_webhooks
SET
  url = COALESCE($2, url),
  events = CASE
      WHEN $3::text[] IS NULL THEN events
      ELSE $3::text[]
    END,
  include_progress = COALESCE($4, include_progress),
  active = COALESCE($5, active),
  secret = COALESCE($6, secret),
  -- Reativar limpa o histórico de falhas. Sem isso, um webhook religado depois
  -- de o cliente consertar o endpoint já nasceria a uma falha do desligamento
  -- automático.
  consecutive_failures = CASE
      WHEN COALESCE($5, active) THEN 0
      ELSE consecutive_failures
    END,
  disabled_reason = CASE
      WHEN COALESCE($5, active) THEN NULL
      ELSE disabled_reason
    END,
  updated_at = now()
WHERE id = $1
  AND deleted_at IS NULL
RETURNING id, integration_id, url, secret, events, include_progress, active, last_delivery_at, last_status_code, last_error, consecutive_failures, disabled_reason, created_at, updated_at, deleted_at
`

type UpdateIntegrationWebhookParams struct {
	ID              uuid.UUID   `json:"id"`
	Url             pgtype.Text `json:"url"`
	Events          []string    `json:"events"`
	IncludeProgress pgtype.Bool `json:"include_progress"`
	Active          pgtype.Bool `json:"active"`
	Secret          pgtype.Text `json:"secret"`
}

func (q *Queries) UpdateIntegrationWebhook(ctx context.Context, arg UpdateIntegrationWebhookParams) (IntegrationWebhook, error) {
	row := q.db.QueryRow(ctx, updateIntegrationWebhook,
		arg.ID,
		arg.Url,
		arg.Events,
		arg.IncludeProgress,
		arg.Active,
		arg.Secret,
	)
	var i IntegrationWebhook
	err := row.Scan(
		&i.ID,
		&i.IntegrationID,
		&i.Url,
		&i.Secret,
		&i.Events,
		&i.IncludeProgress,
		&i.Active,
		&i.LastDeliveryAt,
		&i.LastStatusCode,
		&i.LastError,
		&i.ConsecutiveFailures,
		&i.DisabledReason,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}

const updateWebhookDeliveryResult = `-- name: UpdateWebhookDeliveryResult :exec
UPDATE integration_webhook_deliveries
SET status = $1::core.webhook_delivery_status,
    attempts = attempts + 1,
    last_status_code = $2,
    last_error = $3,
    duration_ms = $4,
    delivered_at = CASE
        WHEN $1::core.webhook_delivery_status = 'DELIVERED' THEN now()
        ELSE delivered_at
      END
WHERE id = $5
`

type UpdateWebhookDeliveryResultParams struct {
	Status     CoreWebhookDeliveryStatus `json:"status"`
	StatusCode pgtype.Int4               `json:"status_code"`
	Error      pgtype.Text               `json:"error"`
	DurationMs int32                     `json:"duration_ms"`
	ID         uuid.UUID                 `json:"id"`
}

// O cast explícito não é decoração: o mesmo parâmetro é usado como valor da
// coluna e dentro do CASE, e sem ele o Postgres deduz tipos diferentes para os
// dois usos e recusa a consulta com "inconsistent types deduced for parameter".
// O sintoma é cruel: a entrega acontece, o cliente recebe, e o registro dela
// nunca é atualizado — o painel mostra tudo como pendente para sempre.
func (q *Queries) UpdateWebhookDeliveryResult(ctx context.Context, arg UpdateWebhookDeliveryResultParams) error {
	_, err := q.db.Exec(ctx, updateWebhookDeliveryResult,
		arg.Status,
		arg.StatusCode,
		arg.Error,
		arg.DurationMs,
		arg.ID,
	)
	return err
}

const webhookDeliveryStats = `-- name: WebhookDeliveryStats :one
SELECT
  COUNT(*)::bigint AS total,
  COUNT(*) FILTER (WHERE status = 'DELIVERED')::bigint AS delivered,
  COUNT(*) FILTER (WHERE status = 'FAILED')::bigint AS failed,
  COUNT(*) FILTER (WHERE status = 'PENDING')::bigint AS pending,
  COALESCE(AVG(duration_ms) FILTER (WHERE status = 'DELIVERED'), 0)::int AS avg_duration_ms
FROM integration_webhook_deliveries
WHERE integration_id = $1
  AND created_at >= now() - ($2::int * INTERVAL '1 hour')
`

type WebhookDeliveryStatsParams struct {
	IntegrationID uuid.UUID `json:"integration_id"`
	WindowHours   int32     `json:"window_hours"`
}

type WebhookDeliveryStatsRow struct {
	Total         int64 `json:"total"`
	Delivered     int64 `json:"delivered"`
	Failed        int64 `json:"failed"`
	Pending       int64 `json:"pending"`
	AvgDurationMs int32 `json:"avg_duration_ms"`
}

// Números da aba de entregas, na janela que a tela pediu.
func (q *Queries) WebhookDeliveryStats(ctx context.Context, arg WebhookDeliveryStatsParams) (WebhookDeliveryStatsRow, error) {
	row := q.db.QueryRow(ctx, webhookDeliveryStats, arg.IntegrationID, arg.WindowHours)
	var i WebhookDeliveryStatsRow
	err := row.Scan(
		&i.Total,
		&i.Delivered,
		&i.Failed,
		&i.Pending,
		&i.AvgDurationMs,
	)
	return i, err
}
